'use strict';
function scrollResearchTarget(el){if(el)window.scrollTo({top:Math.max(0,el.getBoundingClientRect().top+window.scrollY-(document.body.classList.contains('portfolio-embedded')?document.querySelector('nav').offsetHeight+16:0)),behavior:'auto'});}
const R=window.RESEARCH,$=id=>document.getElementById(id),fmt=(n,d=2)=>Number(n).toLocaleString('en-US',{minimumFractionDigits:d,maximumFractionDigits:d}),money=n=>'$'+fmt(n),views=['overview','research','reliability','shipping'];let active='overview';
$('lastPrice').textContent=money(R.last_wti);$('origin').textContent='Observation date / '+R.forecast_origin;
function show(v){const original=v,aliases={story:'overview',market:'overview',model:'research',test:'research',scenario:'research',robust:'reliability',intervals:'reliability'};v=aliases[v]||v;active=v;history.replaceState(null,'','#'+v);document.querySelectorAll('.view').forEach(e=>e.hidden=e.id!==v);document.querySelectorAll('nav button').forEach(e=>e.classList.toggle('active',e.dataset.view===v));if(v==='overview')market();if(v==='research'){odeChart();backtest();scenario();if(typeof renderExtension==='function')renderExtension();}if(v==='reliability'){robustness();intervalLab();}if(v==='shipping')shippingLab();if(original!==v)scrollResearchTarget($(original));else scrollResearchTarget($(v));}

document.querySelectorAll('[data-view]').forEach(e=>e.onclick=()=>show(e.dataset.view));document.querySelectorAll('[data-go]').forEach(e=>e.onclick=()=>show(e.dataset.go));
$('present').onclick=()=>{document.body.classList.toggle('present');$('present').textContent=document.body.classList.contains('present')?'Exit presentation ↙':'Present ↗';};
document.addEventListener('keydown',e=>{if(['INPUT','SELECT'].includes(e.target.tagName))return;if(document.body.classList.contains('present')&&['ArrowRight','ArrowLeft'].includes(e.key)){e.preventDefault();show(views[(views.indexOf(active)+(e.key==='ArrowRight'?1:views.length-1))%views.length]);}});
const rw20=R.metrics.find(x=>x.model==='Random walk'&&x.horizon===20),ridge20=R.metrics.find(x=>x.model==='Ridge drivers'&&x.horizon===20);
$('findingMetric').textContent=`At 20 observations, the random-walk MAE is ${money(rw20.mae)} per barrel, versus ${money(ridge20.mae)} for the driver-based ridge model. More inputs did not improve this test.`;
function table(head,rows){return '<div class="tablewrap"><table><thead><tr>'+head.map(h=>'<th scope="col">'+h+'</th>').join('')+'</tr></thead><tbody>'+rows.map(row=>'<tr'+(row[0]==='Random walk'?' class="baseline"':'')+'>'+row.map(c=>'<td>'+c+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>';}
function plot(target,rows,series,unit,inspect=false){
 if(!rows.length){$(target).textContent='No observations in this selection.';return;}
 const W=1000,H=340,L=70,T=25,B=48,RR=25,values=rows.flatMap(r=>series.map(s=>r[s.key])).filter(v=>v!==null&&Number.isFinite(v));if(!values.length){$(target).textContent='No observations in this selection.';return;}
 let min=Math.min(...values),max=Math.max(...values);const pad=(max-min||1)*.12;min-=pad;max+=pad;const x=i=>L+i/(rows.length-1||1)*(W-L-RR),y=v=>T+(max-v)/(max-min)*(H-T-B);
 let svg=`<svg viewBox="0 0 ${W} ${H}" xmlns="http://www.w3.org/2000/svg"><text x="${L}" y="15" fill="#566d69" font-size="11">${unit}</text>`;
 for(let k=0;k<5;k++){let v=min+(max-min)*k/4;svg+=`<line x1="${L}" y1="${y(v)}" x2="${W-RR}" y2="${y(v)}" stroke="#e1e7e0"/><text x="${L-10}" y="${y(v)+4}" text-anchor="end" fill="#566d69" font-size="11">${fmt(v,1)}</text>`;}
 series.forEach(s=>{let path='',gap=true;rows.forEach((r,i)=>{let v=r[s.key];if(v===null||!Number.isFinite(v)){gap=true;return;}path+=(gap?'M':'L')+x(i).toFixed(2)+','+y(v).toFixed(2)+' ';gap=false;});svg+=`<path d="${path}" fill="none" stroke="${s.color}" stroke-width="2" ${s.dash?'stroke-dasharray="6 5"':''}/>`;});
 [0,Math.floor((rows.length-1)/2),rows.length-1].forEach(i=>svg+=`<text x="${x(i)}" y="${H-15}" text-anchor="middle" font-size="11" fill="#566d69">${rows[i].date}</text>`);
 series.forEach((s,i)=>svg+=`<text x="${L+i*225}" y="${H-1}" font-size="11" fill="${s.color}">${s.name}</text>`);svg+='</svg>';$(target).innerHTML=svg;
 if(inspect){$(target).onpointermove=e=>{let b=$(target).getBoundingClientRect(),i=Math.max(0,Math.min(rows.length-1,Math.round(((e.clientX-b.left)/b.width*W-L)/(W-L-RR)*(rows.length-1))));$('hoverRead').textContent=rows[i].date+' · '+series.map(s=>s.name+': '+(rows[i][s.key]===null?'not reported':fmt(rows[i][s.key]))).join(' · ')+' '+unit;};}
}
function market(){const type=$('series').value,period=$('period').value;let rows=R.history,series,unit,note;
 if(type==='prices'){series=[{key:'wti',name:'WTI spot',color:'#087e83'},{key:'brent',name:'Brent spot',color:'#bd6a34'}];unit='USD / barrel';note='Published EIA spot observations. No target interpolation; missing dates remain missing. These are not continuous futures prices.';}
 if(type==='inventory'){series=[{key:'inventory',name:'US commercial crude stocks',color:'#087e83'}];unit='Thousand barrels';note='EIA weekly period-end stocks, excluding the Strategic Petroleum Reserve. Not global inventory.';rows=rows.filter(r=>r.inventory!==null);}
 if(type==='flows'){series=[{key:'production',name:'US crude production',color:'#087e83'},{key:'demand',name:'US product supplied',color:'#bd6a34'}];unit='Thousand barrels / day';note='EIA weekly estimates. Product supplied is a demand proxy; these two series are not a complete balance because their product coverage differs.';rows=rows.filter(r=>r.production!==null);}
 if(type==='risk'){series=[{key:'ovx',name:'OVX · oil ETF options',color:'#bd6a34'},{key:'vix',name:'VIX · equity options',color:'#087e83'}];unit='Index points';note='Published Cboe indices. Implied volatility is distinct from realized spot-price volatility.';}
 if(type==='global'){rows=R.global_balance.filter(r=>r.date<'2027-01-01').map(r=>({...r,production:r.date>='2026-10-01'?null:r.production,consumption:r.date>='2026-10-01'?null:r.consumption,production_forecast:r.date>='2026-09-01'?r.production:null,consumption_forecast:r.date>='2026-09-01'?r.consumption:null}));series=[{key:'production',name:'Production estimate',color:'#087e83'},{key:'consumption',name:'Consumption estimate',color:'#bd6a34'},{key:'production_forecast',name:'Production forecast',color:'#087e83',dash:true},{key:'consumption_forecast',name:'Consumption forecast',color:'#bd6a34',dash:true}];unit='Million barrels / day';note='October 2026 EIA vintage. Historical estimates through September 2026; October–December 2026 are EIA forecasts. Coverage begins in 2022. Not used for backtests.';}
 if(type==='vol'){rows=R.volatility;series=[{key:'ewma_dollar_sigma',name:'EWMA daily dollar-change sigma',color:'#087e83'}];unit='USD / barrel per observation';note='Derived with EWMA λ=0.94 on dollar changes. Fixed smoothing assumption; not GARCH, annualized return volatility or an OVX equivalent.';}
 if(period!=='all')rows=rows.filter(r=>r.date.startsWith(period));$('chartNote').textContent=note;plot('marketChart',rows,series,unit,true);$('hoverRead').textContent=rows.length?`${rows.length} dated rows in this selection. Move across the plot to inspect values.`:'No data in this period.';
}
$('series').onchange=market;$('period').onchange=market;
$('csv').onclick=()=>{const keys=['date','wti','brent','inventory','production','demand','ovx','vix'],csv=keys.join(',')+'\n'+R.history.map(r=>keys.map(k=>r[k]??'').join(',')).join('\n'),u=URL.createObjectURL(new Blob([csv],{type:'text/csv'})),a=document.createElement('a');a.href=u;a.download='verified-observations-2020-2026.csv';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);};
function odeChart(){let a=.8,b=.4,g=.5,d=.6,z=[1.8,1],rows=[];const f=q=>[q[0]*(-a+b*q[1]),q[1]*(d-g*q[0])],dt=.01;for(let i=0;i<=3000;i++){if(i%10===0)rows.push({date:fmt(i*dt,1),p:z[0],v:z[1]});const k1=f(z),k2=f(z.map((q,j)=>q+dt*k1[j]/2)),k3=f(z.map((q,j)=>q+dt*k2[j]/2)),k4=f(z.map((q,j)=>q+dt*k3[j]));z=z.map((q,j)=>q+dt*(k1[j]+2*k2[j]+2*k3[j]+k4[j])/6);}plot('odeChart',rows,[{key:'p',name:'Illustrative price index',color:'#087e83'},{key:'v',name:'Illustrative volume index',color:'#bd6a34'}],'Dimensionless index · assumed parameters');}
function backtest(){let h=+$('horizon').value,g=R.metrics.filter(r=>r.horizon===h).sort((a,b)=>a.mae-b.mae);$('metrics').innerHTML=table(['Model','Origins','MAE $/bbl','RMSE $/bbl','Direction','90% coverage'],g.map(r=>[r.model,r.n,fmt(r.mae),fmt(r.rmse),r.model==='Random walk'?'Abstains':fmt(r.direction_accuracy*100,1)+'%',fmt(r.coverage90*100,1)+'% (n='+r.interval_n+')']));let z=R.holdout2026.find(r=>r.horizon===h);$('holdout').innerHTML=`<h3>2026 holdout / ${z.selected_pre2026}</h3><p>Selected using pre-2026 target errors. On ${z.n} origins starting in 2026, MAE is ${money(z.mae)} per barrel; the random-walk comparison is ${money(z.rw_mae)}. Settings remain fixed. These observations are a historical holdout, not an untouched prospective study.</p>`;
 $('forecast').innerHTML=table(['Model','Point projection $/bbl','Empirical lower','Empirical upper'],R.forecasts.filter(r=>r.horizon===h).map(r=>[r.model,money(r.prediction),money(r.lower),money(r.upper)]));$('forecastNote').textContent=`Origin ${R.forecast_origin} · ${h} subsequent WTI observations. Empirical nominal 90% ranges; historical coverage is shown above. These projections are not scenario prices.`;
 const lo=R.bollinger.events[0],hi=R.bollinger.events[1];$('bb').textContent=`Lower-band events were followed by a positive five-observation change ${fmt(lo.five_day_reversal_rate*100,1)}% of the time (n=${lo.n}); upper-band events by a negative change ${fmt(hi.five_day_reversal_rate*100,1)}% (n=${hi.n}). Events overlap and no significance claim is made.`;
}
$('horizon').onchange=backtest;
function scenario(){const s=+$('supply').value,d=+$('demand').value,e=+$('elasticity').value,change=(d-s)/100/e,level=R.last_wti*(1+change),ends=[.1,.5].map(k=>R.last_wti*(1+(d-s)/100/k)).sort((a,b)=>a-b);$('supplyOut').textContent=fmt(s,2)+'%';$('demandOut').textContent=fmt(d,2)+'%';$('elasticityOut').textContent=fmt(e);$('scenarioPrice').textContent=money(level);$('scenarioDelta').textContent=(change>=0?'+':'')+fmt(change*100,1)+'% relative to the '+money(R.last_wti)+' anchor';$('scenarioRange').textContent=`Elasticity sensitivity: ${money(ends[0])}–${money(ends[1])}. Assumption range, not a probability interval.`;}
['supply','demand','elasticity'].forEach(id=>$(id).oninput=scenario);document.querySelectorAll('[data-preset]').forEach(b=>b.onclick=()=>{const v=b.dataset.preset; $('supply').value=v==='supply'?-2:v==='balanced'?-2:0;$('demand').value=v==='demand'||v==='balanced'?-2:0;scenario();});
$('sources').innerHTML=R.manifest.map(s=>`<p><a href="${s.url}">${s.description} ↗</a> · ${s.units} · ${s.start} to ${s.end} · ${s.n} observations</p>`).join('')+`<p><a href="${R.global_source.url}">EIA global balance workbook ↗</a> · ${R.global_source.coverage}</p>`;
market();backtest();scenario();

function robustness(){
 const B=window.ROBUSTNESS,h=+$('robustHorizon').value,v=$('robustView').value,summary=B.summary.by_horizon.find(z=>z.horizon===h);
 $('robustHeadline').textContent=`${B.forecast_count.toLocaleString()} new forecasts across daily sensitivities, a separate 2020 extension and weekly tests. At horizon ${h}, ${summary.beats_rw} of ${summary.n} daily settings beat their matched random walk in MAE. This count describes this grid, not a success probability.`;
 let head,rows,note;
 if(v==='grid'){head=['Setting','Changed factor','Origins','MAE $/bbl','Matched RW','MAE / RW'];rows=B.metrics.filter(z=>z.group==='daily'&&z.period==='All'&&z.horizon===h).map(z=>[z.spec,z.family,z.n,fmt(z.mae),fmt(z.rw_mae),fmt(z.relative_mae,3)]);note='Below 1.000 favors the candidate. Windows cap available matured training rows and are initially shorter than their caps. Every setting is reported; no cherry-picked winner is promoted.';}
 if(v==='period'){head=['Period / check','Model','Origins','MAE','Matched RW','Difference'];rows=B.slices.filter(z=>z.horizon===h).map(z=>[z.period,z.model,z.n,fmt(z.mae),fmt(z.rw_mae),fmt(z.difference)]);note='Annual rows require both origin and target in the same year. Non-overlap uses greedy non-overlapping target spans. Top-1% exclusion is an ex-post influence diagnostic, never a deployable trading rule. Negative differences favor the candidate.';}
 if(v==='inference'){head=['Model','Block length','MAE difference','95% lower','95% upper','Holm p'];rows=B.inference.filter(z=>z.horizon===h).map(z=>[z.model,z.block,fmt(z.difference,3),fmt(z.ci_low,3),fmt(z.ci_high,3),fmt(z.holm_p,4)]);note=`2,000 circular block-bootstrap draws per contrast. Positive difference means worse than the random walk. Holm adjustment covers all ${B.summary.holm_contrasts} model/horizon/block contrasts together. Intervals remain unadjusted exploratory intervals; approximate p-values account for the disclosed comparison family.`;}
 if(v==='coverage'){head=['Period','Model','Past errors cap','Origins','90% coverage','Mean width'];rows=B.coverage.filter(z=>z.horizon===h).map(z=>[z.period,z.model,z.window,z.n,fmt(z.coverage*100,1)+'%',fmt(z.mean_width)]);note='Matured-error calibration windows of 60, 125 and 250 origins; at least 30 errors. A wider interval may increase coverage but reduce precision. No configuration is retuned on its realized coverage.';}
 if(v==='2020'){head=['Separate 2020 model','Origins','MAE','Matched RW','MAE / RW'];rows=B.metrics.filter(z=>z.group==='2020 extension'&&z.period==='2020'&&z.horizon===h).map(z=>[z.spec,z.n,fmt(z.mae),fmt(z.rw_mae),fmt(z.relative_mae,3)]);note='Additional 2017–2019 training history from the frozen files; forecast origins on every WTI observation in 2020, with targets contained in 2020. These scores are separate from the original warm-up design and are not prospective evidence.';}
 if(v==='weekly'){head=['Model','Weekly horizon','Origins','MAE','Matched RW','MAE / RW'];rows=B.metrics.filter(z=>z.group==='weekly'&&z.period==='All').map(z=>[z.spec,z.horizon,z.n,fmt(z.mae),fmt(z.rw_mae),fmt(z.relative_mae,3)]);note='Weekly-frequency experiment always shows all 1, 4 and 12 week horizons, regardless of the daily selector. Friday-labeled last observations, origins every second week, minimum 45 matured training rows. Compare with each row’s matched weekly random walk, not with daily MAE.';}
 if(v==='coverage'&&h===20)note+=' In 2026, random-walk coverage is only 55.3%–68.4% across these windows; the ranges should not be treated as reliably calibrated.';
 $('robustTable').innerHTML=table(head,rows);$('robustNote').textContent=note;$('robustLimits').innerHTML=B.limitations.map(z=>'<li>'+z+'</li>').join('');if(typeof robustVisual==='function')robustVisual();
}
$('robustHorizon').onchange=robustness;$('robustView').onchange=robustness;
